-- Auto-generated by scripts/curriculum/build-level-sql.mjs -- do not
-- hand-edit the lesson content below; regenerate from the source plan
-- JSON instead if something needs to change.

do $$
declare
  v_course_id uuid := 'cf93d5fe-0401-492d-a865-dbebc90e43de';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'How Search Actually Works', 'The existing lessons teach SEO tactics. This one teaches the machine those tactics are aimed at — because without it, SEO advice is just superstition you cannot evaluate.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Crawling: How Google Finds Your Pages', 'Google''s own Search Central team on how Googlebot discovers and fetches pages. Under 7 minutes.', 'https://www.youtube.com/watch?v=JuK7NnfyEuc', 1,
      array['Describe how Googlebot discovers a page it has never seen', 'Explain why a page nobody links to may never be found', 'Name the things that can block a crawler outright'],
      'Everything in SEO happens in three stages, and almost all beginner confusion comes from not knowing which stage a problem lives in.

CRAWLING is stage one: Google finding and fetching your page. INDEXING is stage two: deciding to store it. RANKING is stage three: deciding where it appears for a query. This module covers one and two; the tactics you already learned live in three. If you are not crawled and indexed, no amount of keyword optimisation matters, because you are not in the race at all.

HOW GOOGLEBOT FINDS A PAGE. It follows links — from other sites, and from your own pages to each other. It also reads sitemaps you submit. That is essentially it. A brand new page with no links pointing at it and no sitemap entry may sit undiscovered indefinitely. "I published it and Google has not found it" is usually this, not a penalty.

WHAT BLOCKS A CRAWLER, and these are the things worth checking first when something is invisible:

- robots.txt disallowing the path. This tells crawlers not to fetch. Many site builders ship with a restrictive default, and staging sites often block everything and then go live still blocking.
- A noindex tag left on the page from development.
- Content behind a login, a form, or a paywall — a crawler is an anonymous visitor with no password.
- Content that only appears after heavy JavaScript. Google can render JavaScript, but it is slower and less reliable than plain HTML.

CRAWL BUDGET is a real but overrated concern. Google spends a finite amount of effort on any one site. For a small site this never matters. For a large one, thousands of near-duplicate URLs — every filter combination on a shop, say — waste that effort on pages nobody wants.',
      'Visit yourdomain.com/robots.txt for a site you control or know well and read what it actually says — most people have never looked. Then search Google for site:yourdomain.com. That shows roughly what Google has indexed from the site. If the count is far lower than the number of pages you have published, you have a crawling or indexing problem, not a ranking problem.',
      '[{"question":"You publish a new page and Google has not shown it after a week. What is the most likely cause?","options":["Nothing links to it and it is not in a sitemap, so it has not been discovered","Your content is not good enough to rank","Google penalised the page","You did not use enough keywords"],"correct_index":0},{"question":"Which of these makes a page impossible for Googlebot to crawl?","options":["It sits behind a login","It has a short title","It has few images","It was published recently"],"correct_index":0}]'::jsonb),
    (v_m1, 'Indexing and Ranking: The Rest of the Machine', 'Google Search Central explains what happens between crawling a page and showing it in results. Under 4 minutes.', 'https://www.youtube.com/watch?v=_0QOePCkyK4', 2,
      array['Distinguish being indexed from ranking well', 'Explain why Google may crawl a page and choose not to index it', 'Judge SEO advice against how the system actually behaves'],
      'INDEXED IS NOT THE SAME AS RANKED, and confusing the two wastes enormous effort.

Being indexed means Google has your page stored and is willing to consider it. Ranking is where it places among everything else it could show. A page can be perfectly indexed and appear on page nine. That is not a technical fault — it is a competition you are losing, and the fix is different.

GOOGLE MAY DECLINE TO INDEX a page it crawled successfully. The usual reasons are honest ones: the page is a near-duplicate of another page (Google picks one, called the canonical, and drops the rest), it is very thin, or it is auto-generated boilerplate. If a page is crawled but not indexed, the question to ask is "why would anyone want this specific page rather than the other one?"

WHAT ACTUALLY DRIVES RANKING, in the terms Google itself uses: does the content match what the person meant, is it genuinely useful and reasonably authoritative, does the page work well on a phone and load quickly, and is the searcher''s context — their location and language — a fit. Nobody outside Google knows the weights, and anyone claiming to is selling something.

THE PRACTICAL TEST FOR ANY SEO ADVICE: does it make the page genuinely better for a real person, or is it a trick aimed at the machine? Tricks work briefly and then stop, because Google''s whole business depends on closing them. Advice that makes the page more useful keeps working. That is the most valuable thing on this page — a filter you can apply for the rest of your career to claims you cannot otherwise evaluate.',
      'Take three pieces of SEO advice you have seen online and sort them with the test above. For each, ask: would doing this make the page better for the person reading it? Write one sentence per piece explaining your verdict. You will find some advice is obviously sound, some is obviously a trick, and some genuinely is not clear — noticing that third category is the point.',
      '[{"question":"Search Console shows a page as \"crawled — currently not indexed\". What does that mean?","options":["Google fetched the page but chose not to store it, often because it duplicates another page or is thin","The page is banned from Google permanently","The page ranks poorly for its keyword","Your server was offline when Google visited"],"correct_index":0},{"question":"What is the most reliable test of whether an SEO tactic is worth doing?","options":["Whether it makes the page genuinely more useful to a real reader","Whether it increases the keyword count","Whether a popular blog recommends it","Whether it is difficult to implement"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Search Console: Seeing What Google Sees', 'Google''s own free tool tells you exactly what it thinks of your site. It is the difference between doing SEO and guessing at it, and it costs nothing.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Setting Up Search Console', 'Google''s official introduction to Search Console — what it is and how to get connected. Just over 3 minutes.', 'https://www.youtube.com/watch?v=ONr5Z7VhNFI', 1,
      array['Explain what Search Console shows that no third-party tool can', 'Verify ownership of a site', 'Know which questions Search Console answers and which it does not'],
      'Search Console is Google reporting on your site, from inside Google. Every paid SEO tool in existence is estimating what this shows you directly, for free.

WHAT IT UNIQUELY KNOWS, because it comes from Google rather than being inferred:

- The actual queries people typed before seeing your site, with real impression and click counts
- Which of your pages are indexed, and the specific reason any page is not
- Crawl errors Googlebot hit, and when
- Manual actions — the rare case where a human at Google has penalised your site
- Mobile usability and page experience problems

VERIFYING OWNERSHIP proves the site is yours. The usual routes are adding a DNS record, uploading a file Google gives you, or — easiest if you already use them — through Google Analytics or Tag Manager. The DNS method covers a whole domain including subdomains, which is worth the small extra effort.

Set this up on day one of any site. The data only accumulates from the moment you verify, so a site verified today has no history from last month, and you cannot backfill it. Every week you delay is a week of evidence you will never have.

WHAT IT DOES NOT DO: it does not show competitors, it does not suggest keywords to target, and it will not tell you why a competitor outranks you. Those are what third-party tools are actually for.',
      'Set up Search Console for a site you control — your own, an employer''s, or a free site you make for practice. Complete verification properly. If you have no site at all, create a one-page free site first; having a real property to look at makes every remaining lesson concrete rather than theoretical.',
      '[{"question":"What can Search Console show that paid SEO tools can only estimate?","options":["The actual search queries that showed your site, with real impression and click counts","Your competitors'' traffic","Which keywords are worth targeting next","Your site''s revenue"],"correct_index":0},{"question":"Why should you verify Search Console as early as possible?","options":["Data only accumulates from verification onward and cannot be backfilled","Verification gets harder as a site grows","Early verification improves your ranking","Google charges for late verification"],"correct_index":0}]'::jsonb),
    (v_m2, 'Is My Site Even in Google? The Index Report', 'Google Search Central on the index coverage report — which of your pages made it in, and the exact reason for any that did not. Under 7 minutes.', 'https://www.youtube.com/watch?v=L0UqvdHJaXE', 2,
      array['Read the index report and find pages Google has excluded', 'Interpret the common exclusion reasons', 'Fix the cause rather than resubmitting repeatedly'],
      'This is the report that answers the most basic question in SEO, and the one beginners skip straight past: is my page actually in Google at all?

The report splits your pages into indexed and not indexed, and — this is the valuable part — gives a REASON for each exclusion. The common ones, and what each actually means:

CRAWLED, CURRENTLY NOT INDEXED — Google fetched it and decided against storing it. Usually thin, duplicative or low-value content. Resubmitting will not help; improving the page might.

DISCOVERED, CURRENTLY NOT INDEXED — Google knows the URL exists but has not fetched it yet. Often a crawl-budget signal on large sites, or a very new page. Patience, plus internal links pointing at it.

DUPLICATE, GOOGLE CHOSE A DIFFERENT CANONICAL — Google decided another URL is the primary version. Frequently correct behaviour. If it picked the wrong one, a canonical tag tells it your preference.

EXCLUDED BY NOINDEX TAG — you told it not to index. Almost always a leftover from development. Check this first when a page you want indexed is missing.

BLOCKED BY ROBOTS.TXT — you told it not to crawl. Same story.

SOFT 404 — the page loads with a success code but looks empty or like an error page to Google.

The discipline: fix the CAUSE, then request indexing once. Repeatedly hammering "request indexing" on a page Google has deliberately excluded changes nothing and wastes your afternoon.',
      'Open the index report for your property and find one page that is not indexed. Read the specific reason Google gives. Work out whether it is something you did (a stray noindex, a robots rule) or a judgement Google made about the content. Fix it if it is yours to fix, then request indexing once and note the date so you can check back rather than resubmitting daily.',
      '[{"question":"A page you want indexed shows Excluded by noindex tag. What happened?","options":["The page carries a noindex instruction, usually left over from development","Google decided the content is low quality","Your server was unreachable","The page has too few backlinks"],"correct_index":0},{"question":"What should you do about a page marked \"Crawled — currently not indexed\"?","options":["Improve the page''s substance and distinctiveness, then request indexing once","Request indexing every day until it appears","Delete the page and republish it","Add more keywords to the title"],"correct_index":0}]'::jsonb),
    (v_m2, 'What Are People Actually Searching? The Performance Report', 'Google Search Central on the performance report: real queries, impressions, clicks and average position for your site. About 8 minutes.', 'https://www.youtube.com/watch?v=wTwnFcWUM3k', 3,
      array['Read impressions, clicks, CTR and average position, and know what each means', 'Find queries where you already rank but few people click', 'Use real query data instead of guessing what to write next'],
      'This report is the closest thing to being told what your audience wants, in their own words, for free.

FOUR NUMBERS, and the relationship between them is where the insight lives:

IMPRESSIONS — how often your page appeared in results for a query. Being seen.
CLICKS — how often someone actually clicked through.
CTR — clicks divided by impressions. What proportion of people who saw you chose you.
AVERAGE POSITION — roughly where you appeared. Position 1 is the top result.

THE HIGHEST-VALUE PATTERN, and you can act on it this week: sort by impressions and look for queries with MANY IMPRESSIONS BUT A LOW CTR at a decent position. That means Google is already showing you to people and they are choosing someone else. The page ranks; the title and description are not persuading anyone. Rewriting those two lines is far cheaper than trying to climb the rankings, and the effect is often immediate.

THE SECOND PATTERN: queries at position 8 to 20. You are on page two, where almost nobody looks. These are pages that Google already considers relevant and that need a modest push — a bit more depth, a clearer answer to the actual question — rather than a new page from scratch.

THE THIRD, and the one that changes what you write: read the actual query text. People search in ways you would never predict, and often in words your industry does not use. Every query in that list is a real person''s real phrasing. That is better than any keyword tool''s guesses, because it is what actually happened on your site.',
      'Open the performance report, set the date range to the last three months, and sort by impressions. Find one query with a lot of impressions and a CTR under about 2%. Look at the page it points to, and rewrite its title and meta description to speak directly to what that query is asking. Note the date, and check back in a few weeks — this is one of the few SEO changes with a fast, visible result.',
      '[{"question":"A query shows 5,000 impressions, average position 6, and a CTR of 0.4%. What does that suggest?","options":["You rank well enough to be seen, but the title and description are not persuading people to click","The page is not indexed","The keyword is too competitive to pursue","Google is penalising the page"],"correct_index":0},{"question":"Why is the query list more useful than a keyword research tool for deciding what to write?","options":["It is the real wording people used to reach your site, not an estimate","It shows search volume more precisely","It includes competitors'' keywords","It updates faster"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
